head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isurCd = "";          // 발행기관코드 — 부모 콤보의 발행회사 (부모 arr[0])
scwin.isurNm = "";          // 발행기관명 (부모 arr[1])
scwin.secugrpId = "";       // 증권그룹ID (부모 arr[2])
scwin.mktId = "";           // 시장구분코드 (부모 arr[3])
scwin.tpCd = "";            // 관리종목지정업무구분코드 0: 지정 (부모 arr[5])
scwin.selTp = "";           // 선택 구분 2: 발행회사 (부모 arr[7])
scwin.curDate = "";         // 서버 현재일 (yyyyMMdd)
scwin.trJob = "";           // 처리구분 I: 저장, D: 삭제
scwin.isSaved = false;      // 저장·삭제에 성공했는지 — 닫을 때 부모에 돌려준다
scwin.isRegistered = false; // 그리드 종목이 등록됐는지 — 등록 뒤 수정 상태(원본 buttonSet.setUpdateStatus)
scwin.selRow = -1;          // 그리드에서 고른 행 (원본 selectedGrdNum) — 해제·사유변경·안내문작성 대상
scwin.DSCL_FORM_CD = "68344";   // 공시안내문 서식코드 (원본 arr[0])
scwin.DSCL_MKT_ID = "1";        // 공시안내문 시장구분 (원본 arr[3])
scwin.RSNCD_ADM_DESIGN = "2";   // 관리종목지정사유 (pcc list_common RSNCD_ADM_DESIGN)
scwin.DEFAULT_GRND_REGUL = "유가증권시장상장규정 제149조의6제1항";    // 신규 근거규정 기본값
scwin.DEFAULT_REMK = "상기 상장지수증권은 다음 반기말까지 관리종목 지정사유를 해소하지 못할 경우 상장 폐지됨을 알려드립니다.\n";   // 신규 기타 기본값 (원본 fn_setRemk)
// 원본 : /etn/ULDSTF08032_new.gfm (ETN 관리종목지정 — 발행회사 기준 신규)
/*
 * 화면 동작 — (팝업)관리종목지정(발행회사)
 *  - 부모(ULDSTF08031)가 「발행회사」 기준 신규 지정일 때 openPopup 의 data 로 연다. 신규 전용이다 — 수정은 ULDSTF08032 가 한다.
 *  - 발행회사의 종목 여러 개를 그리드에 담고, 같은 지정일·지정사유·근거규정으로 한 번에 등록한다(종목마다 업무처리번호가 서버에서 채번된다).
 *  - 등록 뒤 행을 고르면 그 종목의 마스터를 조회하고, [삭제]·[해제]·[사유변경]·[안내문작성]은 고른 행(삭제는 전 행)으로 한다.
 *  - [해제]·[사유변경]: 형제 팝업을 직접 열지 않고 { next } 로 돌려준다 — 부모가 재조회 뒤 연다(공통 계약서 §3.2).
 *  - 공시안내문작성(ULDSTF92024, 서식 68344). 닫힌 뒤 반환 { isSaved } 또는 X 닫기면 부모가 목록을 다시 조회한다.
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF08032_new/ULDSTF08032_new.md (§번호는 이 문서의 절)
 */

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
// [수정]은 명세에 이 화면의 수정 API 가 없어 상태와 관계없이 잠근다(override — §9·§10).
scwin.BTN_MAP = {
    save : "btn_Save",          // [저장]
    modify : "btn_Update",      // [수정]
    "delete" : "btn_Delete",    // [삭제]
    guide : "btn_Dscl"          // [안내문작성]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08032_new.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 초기화. 버튼을 잠그고 달력 검사를 건 뒤, 부모 파라미터를 받아 신규 기본값을 넣는다. (원본 gform onload — §3)
 *
 * 부모는 openPopup 의 3번째 인자를 평면으로 넘기므로 $c.data.getParameter() 로 받는다(원본 fn_GetPar arr 0~7 — 계약서 §3.1).
 * 원본은 업무처리번호와 관계없이 늘 신규 작성(fn_new_onload)으로 시작한다 — 이 화면은 신규 전용이다.
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
    // 1) 로딩 동안 버튼 잠금
    $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);
    btn_release.setDisabled(true);
    btn_rsn_change.setDisabled(true);

    // 2) 달력 검사(규칙 37)·서버 현재일
    $c.date.checkCalendarFormat(edt_MktactEnforceDd, "yyyyMMdd");
    scwin.curDate = $c.date.getServerDateTime("yyyyMMdd");

    // 3) 파라미터 수신 — openPopup 의 3번째 인자
    const param = $c.data.getParameter() ?? {};

    scwin.isurCd = param.isurCd ?? "";
    scwin.isurNm = param.isurNm ?? "";
    scwin.secugrpId = param.secugrpId ?? "";
    scwin.mktId = param.mktId ?? "";
    scwin.tpCd = param.admisuDesignBzTpCd ?? "";
    scwin.selTp = param.selTp ?? "";

    // 4) 신규 기본값
    scwin.initNewForm();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @event
 * @name scwin.img_SetIsuCd_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목선택 클릭. 원본은 ETN 종목 다건 선택 팝업(fn_PopFindEtnCode)에서 발행회사의 종목을 골라 그리드를 바꿨다. (§6.3)
 *
 * 대응하는 팝업이 아직 전환되지 않았다(파일명 불명, pcc 대응 없음) — 공통 계약서 §3.4 대로 버튼은 두고 안내만 한다(§10 #1).
 * 이 팝업이 없으면 이 화면은 종목을 담을 수 없다 — 전환 전까지 발행회사 기준 신규 지정은 쓸 수 없다.
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.img_SetIsuCd_onclick = async function (e) {
    try {
        // TODO: ETN 종목 다건 선택 팝업 전환 뒤 연결 — 반환 행을 dlt_isuTemp 에 담고 status "N" (§10 #1)
        await $c.win.alert("ETN 종목 선택 팝업이 아직 준비되지 않았습니다.\n\n관리종목지정 목록에서 종목 기준으로 신규 등록하세요.");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08032_new.img_SetIsuCd_onclick" });
    }
};

/**
 * @event
 * @name scwin.grd_isu_oncellclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목 그리드 셀 클릭. 고른 행을 대상으로 삼고 등록된 행이면 그 종목의 마스터를 조회한다. (원본 grid_1 OnClick → fn_SelectGridRow)
 * @param {Number} row 행 index
 * @param {Number} col 열 index
 * @param {String} colId 열 id
 * @returns
 * @hidden N
*/
scwin.grd_isu_oncellclick = async function (row, col, colId) {
    try {
        await scwin.selectGridRow(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08032_new.grd_isu_oncellclick" });
    }
};

/**
 * @event
 * @name scwin.btn_rsn_add_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 사유추가 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_rsn_add_onclick = async function (e) {
    try {
        await scwin.openRsnPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08032_new.btn_rsn_add_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_rsn_del_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 사유삭제 클릭. 지정사유 그리드에서 고른 행을 지운다. (원본 dts_Rsn.DeleteRow(RowPosition))
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_rsn_del_onclick = async function (e) {
    try {
        const row = grd_rsn.getFocusedRowIndex();
        if (row < 0) return;

        dlt_rsn.removeRow(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08032_new.btn_rsn_del_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_Save_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 저장 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_Save_onclick = async function (e) {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08032_new.btn_Save_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_Delete_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 삭제 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_Delete_onclick = async function (e) {
    try {
        await scwin.remove();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08032_new.btn_Delete_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_Dscl_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 안내문작성 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_Dscl_onclick = async function (e) {
    try {
        await scwin.writeDscl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08032_new.btn_Dscl_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_release_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 해제 버튼 클릭. 고른 종목의 관리종목지정 해제(ULDSTF08033) 화면을 부모에 요청하며 닫는다. (원본 fn_release)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_release_onclick = async function (e) {
    try {
        await scwin.requestNext("ULDSTF08033", "4");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08032_new.btn_release_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_rsn_change_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 사유변경 버튼 클릭. 고른 종목의 관리종목 사유변경(ULDSTF08034) 화면을 부모에 요청하며 닫는다. (원본 fn_rsnChange)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_rsn_change_onclick = async function (e) {
    try {
        await scwin.requestNext("ULDSTF08034", "1");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08032_new.btn_rsn_change_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectMst
 * @author Inswave
 * @date 2026. 10. 30
 * @description 고른 종목의 업무처리번호로 상세 조회(묶음)를 불러 마스터만 dma_mst 에 담는다. (원본 fn_search — 08032_new 는 마스터만, §5.1)
 *
 * 종목·지정사유 그리드는 입력한 그대로 둔다 — 같은 사유로 일괄 등록한 화면이라 다시 읽지 않는다(원본과 같음).
 * @param {String} bzProcsNo 업무처리번호
 * @param {String} isurCd 발행기관코드
 * @returns
 * @hidden N
*/
scwin.selectMst = async function (bzProcsNo, isurCd) {
    const sbmOptions = {
        id : "sbm_selectOne",
        method : "get",
        action : "/api/listing/lstproc/etn/adm-isu/select-one",
        isProcessMsg : false
    };

    const requestData = {
        bzProcsNo : bzProcsNo,          // 업무처리번호
        orgBzProcsNo : "",              // 원 지정 업무처리번호 (지정 화면은 쓰지 않음)
        isurCd : isurCd                 // 발행기관코드
    };

    // 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다.
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);

    if (!result.responseJSON?.success) return;

    const mst = result.responseJSON.body?.mst;
    if (mst) dma_mst.setJSON(mst);
};

/**
 * @method
 * @name scwin.checkDoubleInput
 * @author Inswave
 * @date 2026. 10. 30
 * @description 같은 종목·같은 지정일로 이미 입력된 관리종목 건이 있으면 안내하고 true 를 돌려준다. 종목마다 부른다. (원본 fn_check_bz_doubleinput_etn — §5.2)
 * @param {String} isuCd 종목코드
 * @returns {Promise<Boolean>} 중복 여부
 * @hidden N
*/
scwin.checkDoubleInput = async function (isuCd) {
    dma_chkDbl.setEmptyValue();

    const sbmOptions = {
        id : "sbm_checkDoubleInput",
        method : "get",
        action : "/api/listing/lstproc/etn/adm-isu/check-double-input",
        target : "dma_chkDbl=body",
        isProcessMsg : false
    };

    const requestData = {
        isuCd : isuCd,                                          // 종목코드
        mktactEnforceDd : dma_mst.get("mktactEnforceDd"),      // 지정일
        bzProcsNo : ""                                          // 신규 전용 — 자기 건 없음
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);

    if (!result.responseJSON?.success) return true;     // 확인하지 못하면 저장하지 않는다

    if (dma_chkDbl.get("dupYn") === "Y") {
        await $c.win.alert("[" + dma_chkDbl.get("disclsProcsStatCd") + "]건으로 " + dma_chkDbl.get("disclsProcsDdtm") + "에 이미 입력되어있습니다.");
        return true;
    }

    return false;
};

/**
 * @method
 * @name scwin.checkStatus
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목의 최신 관리종목 처리건으로 지정을 저장할 수 있는지 판단한다. 종목마다 부른다. (원본 fn_getMstStatus_etn — §5.3)
 *
 * 명세는 등록 API 가 같은 확인을 서버에서 한다고 적었지만, 원본처럼 저장 전에 사유를 먼저 안내한다.
 *  - 최신 건의 시행일이 입력한 지정일 이후(같은 날 포함)면 MSG-0020
 *  - 지정은 최신 건이 없거나 해제(4)일 때만 저장할 수 있다 — 아니면 MSG-0021
 * @param {String} isuCd 종목코드
 * @returns {Promise<Boolean>} 저장 가능 여부
 * @hidden N
*/
scwin.checkStatus = async function (isuCd) {
    dma_status.setEmptyValue();

    const sbmOptions = {
        id : "sbm_selectOneStatus",
        method : "get",
        action : "/api/listing/lstproc/etn/adm-isu/select-one-status",
        target : "dma_status=body",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { isuCd : isuCd });

    if (!result.responseJSON?.success) return false;

    const lastTpCd = dma_status.get("admisuDesignBzTpCd");     // 최신 건 업무구분
    const lastDd = dma_status.get("mktactEnforceDd");          // 최신 건 시행일

    if (!$c.util.isEmpty(lastDd) && lastDd >= dma_mst.get("mktactEnforceDd")) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0020", ""));
        return false;
    }

    // 지정은 직전 이력이 없거나 해제여야 한다.
    if (!$c.util.isEmpty(lastTpCd) && lastTpCd !== "4") {
        await $c.win.alert($c.stf.getMessageParam("MSG-0021", ""));
        return false;
    }

    return true;
};

/**
 * @method
 * @name scwin.saveTrs
 * @author Inswave
 * @date 2026. 10. 30
 * @description 관리종목지정 일괄 등록. 그리드의 종목코드 목록(isuCdList)과 마스터·지정사유를 한 번에 보낸다. (원본 fn_save 의 종목 루프 + fn_save_trs + trs OnSuccess — §5.4)
 *
 * 원본은 종목마다 화면에서 채번하고 한 건씩 trs.Post 를 던졌다(응답 카운터 trsCnt 로 결과를 맞춤).
 * 명세는 isuCdList 를 받아 종목마다 서버가 채번해 한 트랜잭션으로 저장한다 — 일부만 성공하는 경우가 없다.
 * 응답의 저장된 업무처리번호 목록(bzProcsNoList)을 그리드 행 순서대로 붙인다.
 * @param
 * @returns {Promise<Boolean>} 처리 성공 여부
 * @hidden N
*/
scwin.saveTrs = async function () {
    dma_saveResult.setEmptyValue();

    const sbmOptions = {
        id : "sbm_saveTrs",
        method : "post",
        action : "/api/listing/lstproc/etn/adm-isu/register-design",
        target : "dma_saveResult=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    const isuCdList = dlt_isuTemp.getAllJSON().map(row => row.isuCd);

    const requestData = {
        mstDto : {
            bzProcsNo : "",                                             // 다건 등록은 종목마다 서버 채번
            isuCd : isuCdList[0] ?? "",                                 // 대표 종목코드
            mktactEnforceDd : dma_mst.get("mktactEnforceDd"),          // 지정일
            grndRegulNm : dma_mst.get("grndRegulNm"),                  // 근거규정
            admisuRsnContn : dma_mst.get("admisuRsnContn"),            // 관리종목사유내용
            admisuDesignBzProcsNo : "",                                 // 지정은 서버가 자기 번호로 설정
            remk : dma_mst.get("remk")                                  // 기타
        },
        rsnList : dlt_rsn.getAllJSON().map(row => ({
            admisuDesignRsnCd : row.admisuDesignRsnCd,
            admisuDesignRsnNm : row.admisuDesignRsnNm
        })),
        isuCdList : isuCdList                                           // 발행사 단위 다건 지정
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);

    if (!result.responseJSON?.success || dma_saveResult.get("result") === "F") {
        // "MSG-A002": "[^] 처리 실패하였습니다." — 서버 메시지가 있으면 함께 보인다.
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장") + ($c.util.isEmpty(dma_saveResult.get("resultMessage")) ? "" : "\n\n" + dma_saveResult.get("resultMessage")));
        dlt_isuTemp.getAllJSON().forEach((row, i) => dlt_isuTemp.setCellData(i, "status", "N"));
        return false;
    }

    scwin.applyBzProcsNoList(result.responseJSON.body);

    // "com_complete_0096": "$[0] 되었습니다."
    await $c.win.alert($c.data.getMessage("com_complete_0096", "저장"));
    scwin.isSaved = true;
    scwin.isRegistered = true;

    // 원본: 한 종목이면 그 행을 고른다(fn_SelectGridRow(1)).
    if (dlt_isuTemp.getRowCount() === 1) await scwin.selectGridRow(0);

    scwin.setFormState();
    return true;
};

/**
 * @method
 * @name scwin.removeTrs
 * @author Inswave
 * @date 2026. 10. 30
 * @description 관리종목지정 한 건 삭제. 업무처리번호만 보낸다. (원본 fn_delete 의 종목 루프 한 회 — §5.5)
 *
 * 시장안내공시가 승인된 건은 서버가 삭제를 거부한다(명세 — _new 화면에도 적용).
 * @param {String} bzProcsNo 업무처리번호
 * @returns {Promise<Boolean>} 처리 성공 여부
 * @hidden N
*/
scwin.removeTrs = async function (bzProcsNo) {
    dma_saveResult.setEmptyValue();

    const sbmOptions = {
        id : "sbm_removeTrs",
        method : "post",
        action : "/api/listing/lstproc/etn/adm-isu/remove",
        target : "dma_saveResult=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    // 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다. 그러면 남은 행은 처리하지 않는다.
    const result = await $c.sbm.executeDynamic(sbmOptions, { bzProcsNo : bzProcsNo });

    return (result.responseJSON?.success === true && dma_saveResult.get("result") !== "F");
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.initNewForm
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 기본값. 근거규정·기타 표준 문구를 넣고 그리드를 비운다. (원본 fn_new_onload + dts_Mst OnLoadCompleted — §3)
 * @param
 * @returns
 * @hidden N
*/
scwin.initNewForm = function () {
    dma_mst.setEmptyValue();
    dlt_isuTemp.removeAll();
    dlt_rsn.removeAll();

    dma_mst.set("isurCd", scwin.isurCd);
    dma_mst.set("grndRegulNm", scwin.DEFAULT_GRND_REGUL);
    dma_mst.set("remk", scwin.DEFAULT_REMK);

    scwin.isRegistered = false;
    scwin.selRow = -1;
    scwin.setFormState();
};

/**
 * @method
 * @name scwin.selectGridRow
 * @author Inswave
 * @date 2026. 10. 30
 * @description 그리드 행을 대상으로 삼는다. 등록된 행(업무처리번호 있음)이면 그 종목의 마스터를 조회하고 버튼 상태를 맞춘다. (원본 fn_SelectGridRow — §6.1)
 * @param {Number} row 행 index
 * @returns
 * @hidden N
*/
scwin.selectGridRow = async function (row) {
    if (row < 0 || row >= dlt_isuTemp.getRowCount()) return;

    scwin.selRow = row;

    const bzProcsNo = dlt_isuTemp.getCellData(row, "bzProcsNo");
    if (!$c.util.isEmpty(bzProcsNo)) {
        await scwin.selectMst(bzProcsNo, dlt_isuTemp.getCellData(row, "isurCd"));
    }

    scwin.setFormState();
};

/**
 * @method
 * @name scwin.applyBzProcsNoList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 등록 응답의 업무처리번호 목록을 그리드 행 순서대로 붙이고 처리결과를 Y 로 둔다. (원본 trs OnSuccess 의 BZ_PROCS_NO·STATUS 기록)
 *
 * 목록(bzProcsNoList)이 배열이든 쉼표 문자열이든 받는다(응답 형태 미확정 — §10 #4). 행 수와 다르면 한 종목일 때만 bzProcsNo 를 쓴다.
 * @param {Object} body 등록 응답 본문
 * @returns
 * @hidden N
*/
scwin.applyBzProcsNoList = function (body) {
    const raw = body?.bzProcsNoList;
    const list = Array.isArray(raw) ? raw : String(raw ?? "").split(",").map(v => v.trim()).filter(v => v !== "");
    const rowCount = dlt_isuTemp.getRowCount();

    dlt_isuTemp.setBroadcast(false);
    for (let i = 0; i < rowCount; i++) {
        let bzProcsNo = list[i] ?? "";
        if (list.length !== rowCount && rowCount === 1) bzProcsNo = body?.bzProcsNo ?? "";

        dlt_isuTemp.setCellData(i, "bzProcsNo", bzProcsNo);
        dlt_isuTemp.setCellData(i, "status", "Y");
    }
    dlt_isuTemp.setBroadcast(true, true);
};

/**
 * @method
 * @name scwin.setFormState
 * @author Inswave
 * @date 2026. 10. 30
 * @description 등록 여부에 따라 종목선택·버튼·[해제]·[사유변경] 활성을 정한다. (원본 fn_SetIsuCdBtnShow·fn_SetRelAndChgRsnBtnShow·setButtonSetWithDate·setButtonSetWithDate2 — §6.1)
 *  - 등록 전: [저장]만, 종목선택 가능
 *  - 등록 뒤: 원본 조합 그대로 — 고른 행이 공시된 건(dscYn Y)이고 지정일이 지났으면 조회 전용(error), 그 밖에는 [삭제]·[안내문작성]
 *  - [수정]: 이 화면의 수정 API 가 명세에 없어 늘 잠근다 — 수정은 목록에서 ULDSTF08032 로 연다
 *  - [해제]·[사유변경]: 등록 전이거나 미공시(dscYn N)면 잠금
 * @param
 * @returns
 * @hidden N
*/
scwin.setFormState = function () {
    const dscYn = dma_mst.get("dscYn");

    img_SetIsuCd.setDisabled(scwin.isRegistered);

    let status = "insert";
    if (scwin.isRegistered) {
        const enforceDd = dma_mst.get("mktactEnforceDd");
        const isPassed = !$c.util.isEmpty(enforceDd) && scwin.curDate >= enforceDd;     // 지정일 당일 포함 경과
        status = (dscYn === "Y" && isPassed) ? "error" : "update";
    }
    $c.util.setButtonState("grpBtnBox", status, scwin.BTN_MAP, { override : { modify : false } });

    const lockNext = !scwin.isRegistered || dscYn === "N";
    btn_release.setDisabled(lockNext);
    btn_rsn_change.setDisabled(lockNext);
};

/**
 * @method
 * @name scwin.getSelectedRow
 * @author Inswave
 * @date 2026. 10. 30
 * @description [해제]·[사유변경]·[안내문작성] 대상 행. 한 종목이면 그 행, 여럿이면 고른 행이다. 고르지 않았거나 등록되지 않은 행이면 안내하고 -1. (원본 selectedGrdNum == 0 확인)
 * @param
 * @returns {Promise<Number>} 대상 행 index (없으면 -1)
 * @hidden N
*/
scwin.getSelectedRow = async function () {
    const row = (dlt_isuTemp.getRowCount() === 1) ? 0 : scwin.selRow;

    if (row < 0) {
        await $c.win.alert("종목을 선택해 주세요!");
        return -1;
    }
    if ($c.util.isEmpty(dlt_isuTemp.getCellData(row, "bzProcsNo"))) {
        await $c.win.alert("저장되지 않은 종목입니다. 저장한 뒤 처리하세요.");
        return -1;
    }
    return row;
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 30
 * @description 저장 전 입력값을 검증한다. (원본 fn_CheckForm — §6.2)
 *
 * 순서와 문구는 원본을 따른다: 종목 → 지정일(8자리·익일 이후) → 지정사유 → 근거규정(필수·200byte) → 기타(2000byte) → 종목마다 업무 중복입력.
 * @param
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
*/
scwin.validate = async function () {
    if (dlt_isuTemp.getRowCount() === 0) {
        await $c.win.alert("[관리지정종목]을 선택하세요.");
        img_SetIsuCd.focus();
        return false;
    }

    // 지정일 — 원본 checkDdTm("DD", 지정, false): 8자리, 익일 이후
    const enforceDd = dma_mst.get("mktactEnforceDd") ?? "";
    if (enforceDd.length !== 8) {
        await $c.win.alert("[지정일]을 정확히 입력하세요.");
        edt_MktactEnforceDd.focus();
        return false;
    }
    if (scwin.curDate >= enforceDd) {
        await $c.win.alert("[지정일]을 익일 이후로 입력하세요.");
        edt_MktactEnforceDd.focus();
        return false;
    }

    if (dlt_rsn.getRowCount() === 0) {
        await $c.win.alert("[지정사유]를 선택하세요.");
        btn_rsn_add.focus();
        return false;
    }

    if ($c.util.isEmpty(dma_mst.get("grndRegulNm"))) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "근거규정"));
        txb_AdmisuDesignGrndRegulNm.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_AdmisuDesignGrndRegulNm, 200, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txa_Remk, 2000, "기타")) return false;

    // 종목마다 업무 중복입력 확인 (원본 fn_CheckForm 의 종목 루프)
    const rowCount = dlt_isuTemp.getRowCount();
    for (let i = 0; i < rowCount; i++) {
        if (await scwin.checkDoubleInput(dlt_isuTemp.getCellData(i, "isuCd"))) return false;
    }

    return true;
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 30
 * @description 일괄 저장. 검증 → 종목마다 최신 상태 확인 → 사용자 확인 → 등록. (원본 fn_save — §6.4)
 * @param
 * @returns
 * @hidden N
*/
scwin.save = async function () {
    scwin.trJob = "I";

    if (!await scwin.validate()) return;

    const rowCount = dlt_isuTemp.getRowCount();
    for (let i = 0; i < rowCount; i++) {
        if (!await scwin.checkStatus(dlt_isuTemp.getCellData(i, "isuCd"))) return;
    }

    // "[저장] 처리를 하시겠습니까?" 확인 — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.saveTrs();
};

/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 10. 30
 * @description 삭제. 사용자 확인 뒤 그리드의 등록된 종목을 한 건씩 삭제한다. 전부 성공하면 { isSaved : true } 로 닫고, 실패한 행은 남긴다. (원본 fn_delete + trs OnSuccess/OnFail — §6.4)
 *
 * 다건 전송은 for + await 로 앞 건이 끝난 뒤 다음 건을 보낸다(원본의 응답 카운터 방식을 대체).
 * @param
 * @returns
 * @hidden N
*/
scwin.remove = async function () {
    scwin.trJob = "D";

    // "[삭제] 처리를 하시겠습니까?" 확인 — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    const rowCount = dlt_isuTemp.getRowCount();
    let errCnt = 0;

    for (let i = 0; i < rowCount; i++) {
        const bzProcsNo = dlt_isuTemp.getCellData(i, "bzProcsNo");
        const isOk = !$c.util.isEmpty(bzProcsNo) && await scwin.removeTrs(bzProcsNo);

        dlt_isuTemp.setCellData(i, "status", isOk ? "Y" : "N");
        if (isOk) {
            scwin.isSaved = true;
        } else {
            errCnt++;
        }
    }

    if (errCnt > 0) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제") + ($c.util.isEmpty(dma_saveResult.get("resultMessage")) ? "" : "\n\n" + dma_saveResult.get("resultMessage")));

        // 성공한 행을 지워 실패한 행만 남긴다. 뒤에서부터 지워야 index 가 밀리지 않는다.
        dlt_isuTemp.setBroadcast(false);
        for (let i = dlt_isuTemp.getRowCount() - 1; i >= 0; i--) {
            if (dlt_isuTemp.getCellData(i, "status") === "Y") dlt_isuTemp.removeRow(i);
        }
        dlt_isuTemp.setBroadcast(true, true);
        scwin.selRow = -1;
        return;
    }

    await $c.win.alert($c.data.getMessage("com_complete_0096", "삭제"));
    await $c.win.closePopup({ isSaved : true });
};

/**
 * @method
 * @name scwin.openRsnPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 사유찾기(관리종목지정사유) 팝업을 열고 고른 사유를 지정사유 그리드에 더한다. 이미 있는 사유면 안내하고 넣지 않는다. (원본 fn_PopFindClssLstRsnCd + fn_SetParRsnCd — §6.5)
 *
 * 원본 fn_GetParRsnCd 의 arr[0] "1"(시장)·arr[1] "07"(사유구분)·arr[5] "N"(기업인수목적회사)을 data 로 넘긴다.
 * 중복 확인은 화면에서 0부터 센다 — pcc isNewValueForDataSet 은 1부터 세어 첫 행을 보지 못한다(§8).
 * @param
 * @returns
 * @hidden N
*/
scwin.openRsnPopup = async function () {
    const res = await $c.lc.popFindClssLstRsnCd(scwin.RSNCD_ADM_DESIGN, { mkt : "1", rsn : "07", spac : "N" });
    if (res?.isCloseButtonClick === true || $c.util.isEmpty(res?.code)) return;    // 취소·닫기

    const rows = dlt_rsn.getAllJSON();
    if (rows.some(row => row.admisuDesignRsnCd === res.code)) {
        await $c.win.alert("이미 선택하신 사유가 있습니다.");
        return;
    }

    const row = dlt_rsn.insertRow();
    dlt_rsn.setCellData(row, "admisuDesignRsnCd", res.code);
    dlt_rsn.setCellData(row, "admisuDesignRsnNm", res.name ?? "");
};

/**
 * @method
 * @name scwin.requestNext
 * @author Inswave
 * @date 2026. 10. 30
 * @description [해제]·[사유변경] — 고른 종목으로 다음에 열 화면과 그 data 를 반환하며 팝업을 닫는다. 부모(08031)가 목록을 재조회한 뒤 그 화면을 연다. (원본 fn_release·fn_rsnChange — 계약서 §3.2)
 *
 * 원본은 고른 행을 fn_copy_dts 로 옮긴 뒤(발행기관·발행회사명·종목·업무처리번호) 형제 팝업을 열고 자기 창을 닫았다.
 * selTp "0" 은 형제 팝업에서 왔다는 원본 표시(arr[7] "0")이고, 지정업무처리번호는 고른 행의 번호다.
 * @param {String} id 다음 화면 ID (ULDSTF08033 해제 / ULDSTF08034 사유변경)
 * @param {String} tpCd 관리종목지정업무구분코드 (4 해제 / 1 사유변경)
 * @returns
 * @hidden N
*/
scwin.requestNext = async function (id, tpCd) {
    const row = await scwin.getSelectedRow();
    if (row < 0) return;

    const isu = dlt_isuTemp.getRowJSON(row);
    const data = {
        isurCd : isu.isurCd,                    // 원본 arr[0] 발행기관코드 (fn_copy_dts)
        isurNm : isu.comNm,                     // 원본 arr[1] 발행회사명 (fn_copy_dts 의 COM_NM)
        secugrpId : scwin.secugrpId,            // 원본 arr[2] 증권그룹ID
        mktId : scwin.mktId,                    // 원본 arr[3] 시장구분코드
        bzProcsNo : "",                         // 원본 arr[4] 신규 작성 — 업무처리번호 없음
        admisuDesignBzTpCd : tpCd,              // 원본 arr[5]
        isuCd : isu.isuCd,                      // 원본 arr[6] 종목코드
        selTp : "0",                            // 원본 arr[7] "0" — 형제 팝업에서 옴
        admisuDesignBzProcsNo : isu.bzProcsNo   // 원본 arr[8] 지정업무처리번호
    };

    await $c.win.closePopup({ isSaved : scwin.isSaved, next : { id : id, data : data } });
};

/**
 * @method
 * @name scwin.getDsclData
 * @author Inswave
 * @date 2026. 10. 30
 * @description 공시안내문작성(ULDSTF92024)에 넘길 값. 원본 fn_dscl 이 fn_GetPar 로 채우던 arr[0..5] 와 데이터셋 3개(종목·마스터·사유)다. (§6.6)
 *
 * 대상은 고른 행(원본 selectedGrdNum) — 종목 데이터셋은 그 한 행(원본 fn_copy_dts 로 옮긴 dts_Isu), 마스터에는 그 행의 발행회사명.
 * 원본은 arr[4] 를 비우고 arr[5] 를 넣어 길이 6 — 92024 는 본문을 생성하지 않는 서식으로 본다(원본 그대로).
 * @param {Number} row 대상 행 index
 * @returns {Object} 넘길 data
 * @hidden N
*/
scwin.getDsclData = function (row) {
    const isu = dlt_isuTemp.getRowJSON(row) ?? {};

    return {
        formCd : scwin.DSCL_FORM_CD,                            // 원본 arr[0] "68344"
        bzProcsNo : isu.bzProcsNo ?? "",                        // 원본 arr[1] 고른 행 업무처리번호
        isurCd : isu.isurCd ?? "",                              // 원본 arr[2] 고른 행 발행기관코드
        mktId : scwin.DSCL_MKT_ID,                              // 원본 arr[3] "1"
        msg : "",                                               // 원본 arr[4] 비움
        title : isu.isuNm ?? "",                                // 원본 arr[5] 고른 행 종목명
        isu : [isu],                                            // 원본 CopyDataSet(dts_Isu) — 고른 한 행
        mst : [{ ...dma_mst.getJSON(), comNm : isu.comNm ?? "" }],  // 원본 CopyDataSet(dts_Mst) + COM_NM
        rsn : dlt_rsn.getAllJSON()                              // 원본 CopyDataSet(dts_Rsn)
    };
};

/**
 * @method
 * @name scwin.writeDscl
 * @author Inswave
 * @date 2026. 10. 30
 * @description 공시안내문작성. 대상 종목을 정한 뒤 공시안내문작성 팝업(ULDSTF92024)을 data 로 넘겨 열고 닫힐 때까지 기다린다. (원본 fn_dscl — §6.6)
 *
 * 원본은 닫힌 뒤 다시 조회하지 않는다.
 * @param
 * @returns
 * @hidden N
*/
scwin.writeDscl = async function () {
    const row = await scwin.getSelectedRow();
    if (row < 0) return;

    scwin.selRow = row;

    const options = {
        id : "ULDSTF92024",
        popupName : "공시안내문작성",
        width : 745,
        height : 820,
        type : "pageFramePopup"
    };

    // TODO: 경로는 conversion-front 선례(/ui/listingcommon/), 92024 는 아직 getPar 계약이라 수신부 변경 필요 (§10)
    await $c.win.openPopup("/ui/listingcommon/ULDSTF92024.xml", options, scwin.getDsclData(row));
};

/**
 * @method
 * @name scwin.getPar
 * @author Inswave
 * @date 2026. 10. 30
 * @description [호환용 · 임시] 공시안내문작성(ULDSTF92024) 전환본은 아직 부모의 scwin.getPar 를 이름으로 불러 값을 받는다.
 * 92024 가 $c.data.getParameter() 수신으로 바뀌면 이 함수를 지운다. (§6.6, §10, 가이드 §6.5 예외)
 * @param {Array} arr 92024 가 넘기는 빈 배열 — [0] 서식코드 [1] 업무처리번호 [2] 발행기관코드 [3] 시장구분 [4] 비움 [5] 공시제목
 * @param {Object} dltIsu 92024 의 종목 dataList
 * @param {Object} dltMst 92024 의 마스터 dataList
 * @param {Object} dlt2 92024 의 원천 자료 2 (지정사유)
 * @returns {Number} arr 길이
 * @hidden N
*/
scwin.getPar = function (arr, dltIsu, dltMst, dlt2) {
    const data = scwin.getDsclData(scwin.selRow < 0 ? 0 : scwin.selRow);

    arr[0] = data.formCd;
    arr[1] = data.bzProcsNo;
    arr[2] = data.isurCd;
    arr[3] = data.mktId;
    arr[4] = data.msg;
    arr[5] = data.title;

    scwin.fillDataList(dltIsu, data.isu);
    scwin.fillDataList(dltMst, data.mst);
    scwin.fillDataList(dlt2, data.rsn);

    return arr.length;
};

/**
 * @method
 * @name scwin.fillDataList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 컬럼 정의가 비어 있는 92024 의 원천 dataList 에 행 키를 컬럼으로 더하고 행을 채운다. (원본 CopyDataSet 의 헤더 복사 — §6.6)
 * @param {Object} dataList 채울 dataList
 * @param {Array} rows 행 배열
 * @returns
 * @hidden N
*/
scwin.fillDataList = function (dataList, rows) {
    if (!dataList) return;

    Object.keys(rows[0] ?? {}).forEach(key => {
        if (dataList.getColumnIndex(key) < 0) dataList.insertColumn(key);
    });
    dataList.setJSON(rows);
};
